CREATE TEMP TABLE mc_seed_payload ON COMMIT DROP AS
SELECT $mc_seed${"authors":[{"slug":"chase-willden","name":"Chase Willden","jobTitle":"Founder","bio":"Founder of Lextures. Builds adaptive learning systems using Item Response Theory, spaced repetition, and open-source LMS infrastructure for schools and homeschool families.","knowsAbout":["adaptive learning","Item Response Theory","learning management systems","open source education software","assessment design"],"links":{"sameAs":["https://github.com/StudyDrift"],"consentRecordedAt":"2026-08-11"},"status":"active"}],"categories":[{"slug":"getting-started","title":"Getting started","description":"Set up your account, understand Lextures roles, create your first course, and learn the basic navigation used by every learner and educator.","sortOrder":1,"platformPath":"/get-started"},{"slug":"courses","title":"Courses & content","description":"Build course structure, modules, pages, files, syllabi, and reusable learning content. These guides take a course from an empty shell to a clear learning experience.","sortOrder":2,"platformPath":"/platform"},{"slug":"assessment","title":"Assessment & quizzes","description":"Create question banks, quizzes, interactive activities, and assessment rules. Learn how difficulty, delivery, attempts, and integrity controls work together.","sortOrder":3,"platformPath":"/platform/assessment"},{"slug":"grading","title":"Grading & feedback","description":"Configure gradebooks, rubrics, submissions, peer review, curves, and feedback workflows that remain understandable to educators and learners.","sortOrder":4,"platformPath":"/platform/grading"},{"slug":"adaptive","title":"Adaptive learning","description":"Understand learner models, concept relationships, adaptive paths, spaced review, and misconception signals, including what educators control.","sortOrder":5,"platformPath":"/platform/adaptive-learning"},{"slug":"outcomes","title":"Outcomes & standards","description":"Align learning activities to standards and outcomes, define mastery, and read the reports that connect evidence to instructional goals.","sortOrder":6,"platformPath":"/platform/analytics"},{"slug":"enrollment","title":"People & enrollment","description":"Add people, manage sections and roles, sync rosters, handle invitations and waitlists, and use a test learner safely.","sortOrder":7,"platformPath":"/platform"},{"slug":"accounts","title":"Accounts & security","description":"Manage sign-in, single sign-on, multifactor authentication, password rules, active sessions, and account recovery for your organization.","sortOrder":8,"platformPath":"/security"},{"slug":"accessibility","title":"Accessibility & accommodations","description":"Apply learner accommodations and use accessible authoring, keyboard, display, and assistive-technology features throughout Lextures.","sortOrder":9,"platformPath":"/platform/accessibility"},{"slug":"parents","title":"Parents & guardians","description":"Enable the parent portal, pair guardians with learners, manage notifications, and follow progress for one or more children.","sortOrder":10,"platformPath":"/parents"},{"slug":"integrations","title":"Integrations","description":"Connect Lextures with LMS, SIS, automation, calendar, webhook, and API workflows while keeping ownership and failure handling clear.","sortOrder":11,"platformPath":"/integrations"},{"slug":"marketplace","title":"Marketplace & payments","description":"Publish course listings, set pricing and coupons, understand payouts, and respond to refunds and tax-related marketplace states.","sortOrder":12,"platformPath":"/courses"},{"slug":"admin","title":"Administration","description":"Operate institutions and organizations: hierarchy, permissions, platform settings, audit history, exports, and routine governance tasks.","sortOrder":13,"platformPath":"/trust"},{"slug":"mobile","title":"Mobile apps","description":"Use Lextures on supported mobile devices, control notifications, prepare material for intermittent connectivity, and troubleshoot access.","sortOrder":14,"platformPath":"/platform"},{"slug":"self-hosting","title":"Self-hosting","description":"Deploy and maintain a Lextures installation, including prerequisites, configuration, upgrades, backups, and operational checks.","sortOrder":15,"platformPath":"/get-started"},{"slug":"compliance","title":"Privacy & compliance","description":"Understand how Lextures supports privacy obligations, data requests, retention choices, and institutional review without overstating certification.","sortOrder":16,"platformPath":"/trust"}],"articles":[{"kind":"blog","slug":"adaptive-ai-and-education","category":null,"path":"/blog/adaptive-ai-and-education","title":"How Adaptive AI Is Changing What 'Personalized Learning' Actually Means","description":"See how learner models, item response theory, misconception signals, and spaced practice distinguish adaptive learning from fixed branching.","bodyMd":":::key-takeaways\n- Adaptive learning maintains and updates a learner model instead of following a fixed branch.\n- Item response theory can select useful evidence, while spaced practice supports retention over time.\n- Educators need visible reasoning, controls, and misconception signals rather than an unexplained recommendation.\n:::\n\n:::answer\nAdaptive learning is genuinely adaptive when it updates an evidence-based model of what a learner knows and uses that changing estimate to choose the next useful activity. Fixed remediation branches personalize a path but do not adapt a model. Effective systems also expose uncertainty, protect learner data, and give educators control.\n:::\n\nThis article connects the [adaptive learning guide](/resources/guides#p1), [adaptive platform capabilities](/platform/adaptive-learning), and [implementation documentation](/docs/adaptive/how-adaptive-content-decides).\n\n## What is the problem with “personalized learning”?\n\nEvery EdTech company says their product personalizes learning. The word is on the homepage, in the pitch deck, and in every press release. By now it means almost nothing—which is a shame, because the underlying technical idea is one of the more genuinely useful things to happen in education technology in the last two decades.\n\nThe hollow version of personalization looks like this: a learner answers a question incorrectly, and the system shows them a remediation video. A learner finishes a module early, and the system unlocks the next one. This is just branching logic. It is useful, but it is not adaptive in any meaningful sense.\n\nReal adaptation requires a model of the learner—a running estimate of what they know, how confident that estimate is, and what piece of content will move that estimate forward most efficiently. That is a different technical problem, and it has a different solution.\n\n## What does item response theory actually do?\n\nItem Response Theory (IRT) is a family of psychometric models that have been used in standardized testing since the 1950s. The core idea is that every question has measurable properties—difficulty, discrimination, and a guessing factor—and every learner has a latent ability estimate. The model uses the pattern of correct and incorrect responses to update that ability estimate in real time.\n\nThe two-parameter logistic model (2PL) expresses the probability that a learner with ability θ answers an item correctly as:\n\n```\nP(correct | θ) = 1 / (1 + exp(-a(θ - b)))\n```\n\nwhere `a` is the item's discrimination parameter (how sharply it distinguishes between ability levels) and `b` is its difficulty (the ability level at which a learner has an even chance of answering correctly).\n\nThe three-parameter model (3PL) adds a guessing parameter `c` for multiple-choice items where random guessing is possible:\n\n```\nP(correct | θ) = c + (1 - c) / (1 + exp(-a(θ - b)))\n```\n\nIn practice, what this means for a learner is that the system is never just checking whether they got a question right. It is continuously refining a probability distribution over their true ability level. When the estimate has low variance—when the system is confident it knows where a learner sits—it can route them to content that is appropriately challenging. When the estimate is uncertain, it routes them to calibration items that reduce that uncertainty fastest.\n\nThis is categorically different from a \"difficulty slider\" or a \"remediation branch.\" The question selection is not deterministic. It depends on the full posterior distribution over learner ability.\n\n## Why is branching not adaptive?\n\nA common misconception in EdTech is that branching logic and adaptive learning are the same thing. They are not.\n\nBranching says: \"If the learner answered question 3 incorrectly, show them question 3b instead of question 4.\" The path is fixed at authoring time. A subject-matter expert wrote the decision tree, and the system follows it.\n\nAdaptive says: \"Given everything this learner has done so far, which item from the calibrated pool will most efficiently reduce uncertainty about their ability and route them toward their learning objective?\" The path is computed at runtime, from a model.\n\nThe distinction matters because branching does not generalize. It can only handle the cases its author anticipated. An adaptive system handles cases that no author anticipated, including novel combinations of strength and gap that do not map to any predetermined path.\n\n## How does misconception detection work at scale?\n\nIndividual adaptation is only part of the problem. Instructors also need a picture of the whole class.\n\nWhen a student gets a question wrong, there are many possible reasons: they were not paying attention, they guessed, they have a specific conceptual misunderstanding, or the question itself is poorly written. The pattern of wrong answers across many students is much more informative than any individual response.\n\nIf a large share of a class consistently selects the same wrong answer to a particular question, that is not noise. That is a signal about a shared misconception—probably one introduced by a common prior class, a textbook explanation, or a real-world intuition that breaks down in this domain.\n\nSurfacing these patterns automatically changes what an instructor can do in the next class session. Instead of reviewing everything, they can address the specific wrong model that most students have built. That is a qualitatively different use of class time.\n\n## How does spaced repetition make knowledge stick?\n\nAdaptive delivery during a learning session does not solve the retention problem. A learner can demonstrate mastery on Tuesday and have forgotten most of it by the following week—a phenomenon called the forgetting curve, described by Hermann Ebbinghaus in 1885 and reproduced in hundreds of subsequent studies.\n\nSpaced repetition scheduling (SRS) attacks this problem directly. The algorithm schedules review of previously-mastered material at increasing intervals, timed to appear just before the learner is predicted to forget. Initial reviews are close together; as the learner demonstrates retention, intervals grow—hours, then days, then weeks, then months.\n\nThe result is that each review is more efficient than the last. Material that has been reviewed four times at optimal intervals requires far less cognitive effort to retrieve than material that was massed in a single session and not reviewed since.\n\nFor a course that spans weeks or months, this means the LMS is doing work between formal class sessions that most gradebooks do not. It is not just a record of what happened. It is a schedule of what needs to happen next, personalized to each learner's decay rate for each concept.\n\n## What does adaptive learning mean for instructors?\n\nMost of the conversation around adaptive AI in education focuses on the learner experience. That framing misses half the value.\n\nAn instructor facing a class of thirty students cannot individually track each student's running ability estimate, their recent misconceptions, or their optimal review schedule. The cognitive load is too high. So most instructors fall back on assessments: here is what the class got wrong on the midterm, which tells you where students are at that specific point in time.\n\nAdaptive systems shift this from a periodic snapshot to a continuous signal. The instructor sees:\n\n- Which concepts have high variance across the class (some students have mastered them, others have not)\n- Which misconceptions are most prevalent right now, not last week\n- Which students are at risk of falling behind their scheduled review, not because they are lazy but because the system has not scheduled enough touchpoints\n\nThis changes instructional decisions before they matter, not after.\n\n## Why does open source matter for adaptive learning?\n\nMost of the adaptive learning systems deployed in higher education are commercial black boxes. Instructors and institutions do not know how ability estimates are computed, how items are calibrated, or what data the system retains. This is a real problem for institutions that care about data governance, and it creates a lock-in problem: the calibrated item bank is inside the vendor's system.\n\nOpen-source adaptive learning infrastructure changes the calculus. When the IRT engine, the SRS scheduler, and the misconception detection pipeline are inspectable and self-hostable, institutions can:\n\n- Audit the models that are making routing decisions about their students\n- Carry their calibrated item data if they change platforms\n- Contribute improvements back to the shared infrastructure\n\nThe core algorithms are not proprietary. IRT has been in the academic literature for decades. SRS algorithms are well-described and reproducible. What EdTech vendors have historically sold is the implementation and the integration—and those are now commodities.\n\n## Where is adaptive learning heading?\n\nThe near-term trajectory is not AI replacing instructors. It is AI handling the parts of instruction that do not require human judgment—routing, scheduling, pattern detection—so that instructor time is reserved for the parts that do: facilitating discussion, providing feedback on open-ended work, and building relationships with students who are struggling.\n\nThe longer arc is toward learning systems that maintain a persistent model of each learner across their entire educational history—not just within a single course, but across courses, institutions, and years. That is technically achievable. The harder problem is the human one: getting institutions to share data, getting students to trust the model, and building the governance frameworks that make persistent learner models defensible rather than surveillance.\n\nThe technology is not waiting on research breakthroughs. It is waiting on the institutional and policy infrastructure to catch up. That is a slower process, but it is moving.\n\n:::faq\n### Is branching logic the same as adaptive learning?\n\nNo. Branching follows rules fixed by an author, while adaptive learning updates a learner estimate from accumulating evidence. Branching can still be useful, but calling it adaptive hides the model, uncertainty, and selection logic that educators should be able to inspect.\n\n### Does adaptive learning require artificial intelligence?\n\nNot necessarily. Established psychometric and scheduling methods can adapt practice without a generative model. The important questions are what evidence changes the learner model, how the next activity is chosen, and whether educators can understand and override the decision.\n\n### What should a school ask an adaptive-learning vendor?\n\nAsk what the model estimates, how items are calibrated, which data is retained, how uncertainty appears to educators, and whether learners have an accessible alternative. Schools should also test data portability and review the system’s evidence rather than accepting a personalization label.\n:::\n\n[^1]: https://www.ncme.org/resources-publications\n[^2]: https://doi.org/10.1177/1529100612453266\n[^3]: https://doi.org/10.1111/j.1467-9280.2006.01693.x\n[^4]: https://tech.ed.gov/\n[^5]: https://ies.ed.gov/ncee/wwc/PracticeGuides","author":"chase-willden","reviewer":null,"publishedAt":"2026-05-06","contentUpdatedAt":"2026-08-11","reviewedAt":null,"reviewDueOn":"2026-11-06","primaryQuestion":"What makes adaptive learning genuinely adaptive?","cluster":"p1","pillar":"p1","briefRef":"2026-05-adaptive-ai-and-education","verifiedAgainst":"","keywords":["adaptive learning","personalized learning","item response theory","spaced practice"],"relatedTo":[],"roles":[],"segments":[],"citations":["https://doi.org/10.1177/1529100612453266","https://doi.org/10.1111/j.1467-9280.2006.01693.x","https://www.ncme.org/resources-publications"],"extra":{"import":{"sourcePath":"www/src/blog/adaptive-ai-and-education.md","gitSha":"079aacf8fef3b171a54b2063dce723471714b824","importedAt":"2026-08-12T00:00:00Z","lastmodSource":"frontmatter","sourceHash":"a6011d30debeff583d35f23d4b18a5237cd735bdfacbab10970a0213d5d7a009","importedRevision":1,"metadata":{"contentContract":"seo-6-v1"}},"seedMigration":"485"}},{"kind":"blog","slug":"blooms-taxonomy-in-the-age-of-ai","category":null,"path":"/blog/blooms-taxonomy-in-the-age-of-ai","title":"Flipping the Pyramid: Bloom's Taxonomy in the Age of Generative AI","description":"Use Bloom's taxonomy to design visible evidence of reasoning, revision, and transfer when generative AI can produce polished answers.","bodyMd":":::key-takeaways\n- Generative AI makes polished output a weaker proxy for the thinking that produced it.\n- Assessment should make decisions, evidence, revision, and transfer visible across Bloom’s levels.\n- Bloom’s taxonomy remains useful when educators treat it as a design lens rather than a rigid ladder.\n:::\n\n:::answer\nEducators should use Bloom’s taxonomy to design visible evidence of thinking, not simply to label harder-looking outputs. When AI can generate summaries or drafts, assessment should examine how learners select evidence, justify choices, revise work, transfer knowledge, and reflect on the process. Those actions preserve validity across the taxonomy.\n:::\n\nExplore the [assessment guide](/resources/guides#p2), [assessment capabilities](/platform/assessment), and [related assessment analysis](/blog/rethinking-assessment-in-the-ai-era).\n\n## How does the traditional Bloom’s ascent work?\n\nIn 1956, Benjamin Bloom and a committee of educators introduced a classification of educational learning objectives that would define modern pedagogy: the Taxonomy of Educational Objectives. Revised in 2001 by Lorin Anderson and David Krathwohl, the taxonomy organized cognitive operations into a hierarchical pyramid:\n\n1. **Remember:** Retrieve, recall, or recognize relevant knowledge from long-term memory.\n2. **Understand:** Construct meaning from oral, written, and graphic messages through interpreting, exemplifying, classifying, summarizing, inferring, comparing, and explaining.\n3. **Apply:** Carry out or use a procedure in a given situation.\n4. **Analyze:** Break material into constituent parts, determining how the parts relate to one another and to an overall structure or purpose.\n5. **Evaluate:** Make judgments based on criteria and standards through critiquing and monitoring.\n6. **Create:** Put elements together to form a coherent or functional whole; reorganize elements into a new pattern or structure.\n\nFor seventy years, the consensus of instructional design has been linear: **you must walk before you can run.** A student cannot analyze a Shakespearean sonnet (Level 4) without first remembering the definition of iambic pentameter (Level 1) and understanding its rhythm (Level 2). Consequently, the vast majority of classroom time and homework in both K-12 and higher education has been spent consolidating the foundation—climbing the bottom half of the pyramid.\n\nThen came generative AI.\n\n## How does AI change the base of the taxonomy?\n\nThe core disruption of Large Language Models (LLMs) is not that they are \"smart,\" but that they have digitized and scaled the bottom three tiers of Bloom's Taxonomy. \n\n* **Remembering** is now a zero-latency query. An LLM possesses immediate access to an unmatched corpus of historical dates, mathematical formulas, syntax structures, and scientific consensus.\n* **Understanding** is commoditized. Ask a frontier model to \"explain quantum computing to an 8-year-old,\" \"summarize the key arguments of Karl Marx,\" or \"classify these clinical symptoms,\" and it will produce a highly coherent response in seconds.\n* **Applying** is automated. Standard procedural applications—writing a basic Python script, drafting a legal contract template, or solving standard chemistry equations—no longer require manual human execution to be produced.\n\nIf a student can offload Remembering, Understanding, and Applying to an AI assistant with a simple prompt, the traditional linear model of learning collapses. If we continue to assess students primarily on these lower-order tasks, we are no longer measuring human learning; we are measuring their ability to act as an API bridge to an LLM.\n\nAs we argued in our post on [Rethinking Assessment](./rethinking-assessment-in-the-ai-era.md), detection is a dead end. We cannot police our way back to the pre-AI era. Instead, we must change the cognitive sequence of the classroom. We must **flip the pyramid.**\n\n```mermaid\ngraph TD\n    subgraph \"Traditional Linear Approach\"\n        T1[1. Remember] --> T2[2. Understand] --> T3[3. Apply] --> T4[4. Analyze] --> T5[5. Evaluate] --> T6[6. Create]\n        style T1 fill:#e3f2fd,stroke:#1565c0\n        style T2 fill:#e3f2fd,stroke:#1565c0\n        style T3 fill:#e3f2fd,stroke:#1565c0\n        style T4 fill:#ffe0b2,stroke:#ef6c00\n        style T5 fill:#ffe0b2,stroke:#ef6c00\n        style T6 fill:#ffcdd2,stroke:#c62828\n    end\n    \n    subgraph \"AI-Inverted Approach\"\n        I6[6. Create - Co-Generation] --> I5[5. Evaluate - Critique & Verify] --> I4[4. Analyze - Deconstruct & Trace] --> I3[3. Apply - Contextual Transfer] --> I2[2. Understand - Internalize Patterns] --> I1[1. Remember - Active Retrieval]\n        style I6 fill:#ffcdd2,stroke:#c62828\n        style I5 fill:#ffe0b2,stroke:#ef6c00\n        style I4 fill:#ffe0b2,stroke:#ef6c00\n        style I3 fill:#e3f2fd,stroke:#1565c0\n        style I2 fill:#e3f2fd,stroke:#1565c0\n        style I1 fill:#e3f2fd,stroke:#1565c0\n    end\n```\n\n## Why might synthesis become a starting point?\n\nIn the inverted model of Bloom's Taxonomy, the learning journey does not end with synthesis; it *begins* there. \n\nInstead of spending weeks memorizing facts and writing introductory paragraphs, the learner uses AI to generate draft artifacts, models, or solutions immediately. The human cognitive work is shifted upward, focusing on **Evaluation, Analysis, and Refinement**.\n\n### 1. Co-Generation (Creating) as Step One\nIn a flipped workflow, the student acts as a director rather than a scribe. They prompt the AI to generate a first draft, a piece of code, or a proposed solution to a complex problem. By starting at the \"Create\" level, the student is exposed to a holistic, finished product immediately, bypassing the blank-page paralysis that often stalls novice learners.\n\n### 2. Critique and Verification (Evaluating)\nOnce the artifact is generated, the student's primary task is evaluation. They must interrogate the output:\n* *Where is the AI hallucinating or oversimplifying?*\n* *What biases or unstated assumptions are embedded in its argument?*\n* *Does the generated code actually run, and is it optimized for edge cases?*\n\nThis requires the student to hold the AI's output against rigorous external standards, forcing them to engage deeply with evaluative criteria.\n\n### 3. Deconstruction and Lineage (Analyzing)\nTo evaluate the output effectively, the student must deconstruct it. They must analyze how the parts of the generated text or system relate to one another. They trace the logical steps the AI took, looking for flaws in the chain of reasoning.\n\n### 4. Contextual Transfer (Applying)\nThe student takes the critique and applies it to modify the artifact, adapting it to a highly specific, local, or novel context that the AI's general training data could not anticipate. This is where authentic human agency is injected into the project.\n\n### 5. Internalization and Retention (Understanding & Remembering)\nHere is the crucial cognitive pivot: **the lower-order skills are not abandoned; they are acquired retrospectively.** \n\nThrough the intense process of critiquing, analyzing, and refining the AI's output, the student builds a strong mental model of the domain. They *understand* the concepts because they have wrestled with their specific failure modes in the AI's output. They *remember* the facts because those facts were the precise keys needed to unlock and correct the AI's mistakes.\n\n## What does cognitive science say about a flipped Bloom’s model?\n\nThis inversion is not just a pragmatic adjustment to technology; it aligns with foundational principles of cognitive science.\n\n### The Expertise Reversal Effect\nCognitive Load Theory, formulated by John Sweller, describes the **Expertise Reversal Effect**: instructional techniques (like highly structured, step-by-step scaffolding) that are highly effective for novices can become ineffective or even detrimental as learners gain expertise. \n\nFor a novice, starting with a blank slate and trying to write an entire essay induces high *extraneous cognitive load*—their working memory is overwhelmed by spelling, grammar, and sentence structure, leaving no resources for deep conceptual thinking. By using AI to handle the lower-level cognitive load, we can guide novice students through high-level conceptual relationships sooner, bootstrapping their schema development.\n\n### The Generation Effect and Active Recall\nIn our previous discussion on [The Synthetic Renaissance](./the-synthetic-renaissance.md), we noted the danger of cognitive offloading: when students passively consume AI-generated answers, they bypass the **\"Generation Effect\"**—the cognitive phenomenon where self-generated information is retained far better than passive consumption.\n\nFlipping Bloom's Taxonomy preserves the Generation Effect by shifting the \"generation\" from *writing raw sentences* to *generating critiques, justifications, and corrections*. The student is not passively reading the AI's output; they are actively editing, restructuring, and arguing with it. The mental effort is concentrated on the delta between the AI's draft and the final, human-refined masterpiece.\n\n## How can educators operationalize the flipped classroom?\n\nHow do instructors design courses for this inverted flow? Here are three concrete pedagogical strategies:\n\n### 1. The \"Reverse Gradebook\" Assignment (Focus: Evaluation)\nInstead of asking students to write an essay on a historical topic, the instructor provides three AI-generated essays on the subject—one that is highly accurate but surface-level, one that contains subtle factual inaccuracies, and one that suffers from severe logical flaws. \n* **The Task:** Students must act as the professor, annotating the essays, grading them against a detailed [analytic rubric](./effective-rubrics-in-the-age-of-ai.md), and writing a comprehensive critique explaining *why* they awarded those grades.\n* **The Learning:** To spot the subtle inaccuracies and logical flaws, students must deeply research the topic, achieving \"Remembering\" and \"Understanding\" through the act of critique.\n\n### 2. Multi-Turn Prompt Engineering (Focus: Analysis & Application)\nIn computer science or writing courses, students are graded not on their final code or prose, but on their **prompt log**.\n* **The Task:** Students must submit a step-by-step history of their interaction with the LLM. They must document:\n  1. Their initial prompt.\n  2. Their analysis of the AI's first attempt.\n  3. The specific corrective prompts they used to refine the output.\n  4. A final reflection on the limitations of the resulting artifact.\n* **The Learning:** This shifts the grade from the product to the process, measuring the student's metacognitive monitoring and analytical precision.\n\n### 3. The Local Synthesis Project (Focus: Creation & Transfer)\nStudents use AI to generate a general, theoretical framework for solving a problem (e.g., municipal water management, public relations crisis response, or lesson planning).\n* **The Task:** Students must take this abstract framework and apply it to a highly specific, local community scenario (e.g., water quality in their university's town, a specific local business, or a neurodivergent student in a local classroom). They must conduct interviews, collect local data, and modify the AI framework to fit the messy reality of the physical world.\n* **The Learning:** This requires far transfer—a classic sign of true cognitive mastery—and demands authentic, situated human intelligence that LLMs cannot emulate.\n\n## How can assessment elevate the ceiling of education?\n\nThe commoditization of lower-order thinking is terrifying only if we view education as a system for producing compliant informational processors. If our goal is to train students to act as human calculators or database retrievers, then generative AI has indeed rendered that goal obsolete.\n\nBut if we view education as the cultivation of critical, independent, and creative thinkers, then the inversion of Bloom's Taxonomy represents an unprecedented opportunity. By offloading the mechanical, rote, and repetitive aspects of cognitive labor to machines, we can raise the ceiling of what is possible in the classroom.\n\nWe no longer have to spend most of a semester climbing the bottom of the pyramid, leaving only the final weeks for genuine, creative analysis. In the AI era, we can spend more time at the top of the pyramid from day one.\n\n---\n\n*Further reading: Anderson, L. W., & Krathwohl, D. R. (2001). \"A Taxonomy for Learning, Teaching, and Assessing: A Revision of Bloom's Taxonomy of Educational Objectives\"; Sweller, J. (2010). \"Element Interactivity and Intrinsic, Extraneous, and Germane Cognitive Load\"; Wiliam, D. (2011). \"What is Assessment for Learning?\".*\n\n:::faq\n### Is Bloom’s taxonomy obsolete because of AI?\n\nNo. It remains a useful vocabulary for learning goals, but AI makes the visible product less reliable as evidence. Educators should examine the decisions, explanations, revision, and transfer behind the product rather than assuming a sophisticated output demonstrates sophisticated thinking.\n\n### Should every assignment target the highest Bloom’s level?\n\nNo. Learners still need knowledge and practice that support analysis, evaluation, and creation. A balanced sequence chooses the level that fits the learning goal and collects evidence appropriate to that level instead of treating the taxonomy as a race upward.\n\n### Can learners use AI during lower-level practice?\n\nThey can when tool use supports the stated goal and does not erase the evidence an educator needs. The assignment should state what help is permitted, what the learner must do independently, and how understanding will be checked.\n:::\n\n[^1]: https://www.apa.org/ed/schools/teaching-learning/top-twenty-principles.pdf\n[^2]: https://tech.ed.gov/ai-future-of-teaching-and-learning/\n[^3]: https://unesdoc.unesco.org/ark:/48223/pf0000386693\n[^4]: https://udlguidelines.cast.org/\n[^5]: https://ies.ed.gov/ncee/wwc/PracticeGuides\n[^6]: https://www.w3.org/TR/WCAG22/","author":"chase-willden","reviewer":null,"publishedAt":"2026-05-26","contentUpdatedAt":"2026-08-11","reviewedAt":null,"reviewDueOn":"2026-11-26","primaryQuestion":"How should educators use Bloom's taxonomy when generative AI can produce answers?","cluster":"p2","pillar":"p2","briefRef":"2026-05-blooms-taxonomy-ai","verifiedAgainst":"","keywords":["Bloom's taxonomy","generative AI assessment","higher-order thinking"],"relatedTo":[],"roles":[],"segments":[],"citations":["https://www.apa.org/ed/schools/teaching-learning/top-twenty-principles.pdf","https://tech.ed.gov/ai-future-of-teaching-and-learning/","https://unesdoc.unesco.org/ark:/48223/pf0000386693"],"extra":{"import":{"sourcePath":"www/src/blog/blooms-taxonomy-in-the-age-of-ai.md","gitSha":"079aacf8fef3b171a54b2063dce723471714b824","importedAt":"2026-08-12T00:00:00Z","lastmodSource":"frontmatter","sourceHash":"eb38a7e2e0dfc08b9ffbb9dcf6175f47c46b1b929c2680ea5e7fb0e27618d08e","importedRevision":1,"metadata":{"contentContract":"seo-6-v1"}},"seedMigration":"485"}},{"kind":"blog","slug":"effective-rubrics-in-the-age-of-ai","category":null,"path":"/blog/effective-rubrics-in-the-age-of-ai","title":"Beyond Checklists: Designing Rubrics That Still Mean Something When AI Can Write the Essay","description":"Design valid AI-era rubrics around observable reasoning, evidence, revision, and transfer instead of polished output alone.","bodyMd":":::key-takeaways\n- Valid rubrics describe observable reasoning and decisions rather than surface polish alone.\n- Students use criteria more effectively when they receive and discuss them before beginning work.\n- AI can help draft criteria, but an educator must verify alignment, accessibility, and scoring meaning.\n:::\n\n:::answer\nDesign an AI-era rubric around evidence that the learner can explain and defend: choices, source use, revision, transfer, and reflection. Give learners the criteria before they work, distinguish permitted AI assistance from assessed performance, and test whether two reviewers interpret each criterion consistently. Polished prose alone is not valid evidence.\n:::\n\nContinue with the [assessment guide](/resources/guides#p2), [grading platform](/platform/grading), and [assessment redesign article](/blog/rethinking-assessment-in-the-ai-era).\n\n## What is the rubric paradox?\n\nThe most common rubric in higher education describes what a piece of writing *looks like*—clear thesis, supporting evidence, logical transitions, correct grammar. An LLM can produce a document that scores \"proficient\" on every one of those dimensions in under ten seconds.\n\nThis is not a failure of the rubric. It is a revelation. The rubric was always measuring surface features that correlated with understanding, not understanding itself. AI has simply made that distinction unavoidable.\n\nThe research on rubric design has, for years, pointed toward the same conclusion that AI is now forcing. A 2013 meta-analysis by Jonsson and Svingby found that rubrics improve the reliability of scoring *and* student learning—but only when they are designed around the cognitive processes that produce quality work, not the cosmetic properties of the product. The distinction matters more now than ever.\n\n## What do rubrics actually do to learners?\n\nBefore redesigning rubrics for an AI-capable world, it is worth being precise about what rubrics do at all.\n\nHeidi Andrade's foundational work (2005, 2013) established two functions that are often conflated. The first is **evaluative**: rubrics help assessors apply consistent criteria so that two different graders give the same student the same score. The second is **instructional**: rubrics help students internalize quality criteria before they begin working, activating what cognitive load researchers call \"schema-guided self-regulation.\"\n\nThe instructional function is the more consequential one for learning outcomes, and it is also the one most threatened by AI misuse. When a student uses a rubric as a *checklist to verify output* rather than a *map to guide process*, the schema-regulation never occurs. They produce a document that satisfies the criteria without engaging in the cognition the criteria were designed to elicit.\n\nA 2020 study by Brookhart and Chen found that students who received rubrics *before* starting a task showed significantly higher metacognitive monitoring during the writing process than students who received identical rubrics *after* submission. The timing was the intervention. The rubric did not change; the cognitive sequence did.\n\nThe implication for the AI era is direct: if students can use AI to generate the output and then check it against the rubric, the rubric's instructional function is entirely bypassed. Redesigning the rubric must mean redesigning when and how it is encountered—not just what it says.\n\n## How do analytic and holistic rubrics differ?\n\nRubric design research distinguishes three main formats: **holistic** (a single overall judgment), **analytic** (separate scores for each dimension), and **single-point** (describes only the proficient level, leaving space for qualitative feedback above and below).\n\nEach has a different interaction with AI's capabilities.\n\n**Holistic rubrics** are the most resistant to AI gaming because they require a rater to form a gestalt impression of a unified whole. They are also the hardest to use instructionally, because students receive limited actionable feedback. They work best for high-volume, low-stakes formative assessments where speed matters and a single quality signal is sufficient.\n\n**Analytic rubrics** are the most common in K–12 and higher education, and the most vulnerable to AI. When each criterion is scored independently, a student—or an LLM—can optimize each dimension separately, producing a document that scores 4/4 on every row while demonstrating no coherent understanding. Panadero and Jonsson's 2013 review noted that analytic rubrics improve reliability but can fragment assessment into disconnected dimensions that reward compliance over synthesis.\n\n**Single-point rubrics** have seen renewed interest in research precisely because they resist criterion gaming. By describing only the \"proficient\" level and leaving space for instructor commentary rather than pre-defined levels, they create a feedback structure that cannot be reverse-engineered into a production checklist. Fluckiger (2010) found that single-point rubrics generated richer written feedback and higher student engagement with that feedback compared to analytic rubrics in a controlled college writing study.\n\nThe practical recommendation from the research is not to abandon analytic rubrics, but to redesign their criteria. Stop describing the surface features of the output. Start describing the cognitive operations that produce it.\n\n## How can criteria require evidence beyond an AI output?\n\nThe shift from output-descriptive criteria to process-descriptive criteria is the central challenge. The following research-grounded strategies operationalize it.\n\n### Require Explicit Reasoning Traces\n\nRather than \"argument is supported by relevant evidence,\" write: \"Student explains why each piece of evidence is relevant to the specific claim it supports, rather than simply placing evidence adjacent to the claim.\"\n\nThe distinction is subtle but decisive. An LLM will produce text where evidence appears adjacent to claims. It will not, by default, produce text that explicitly unpacks the relevance relationship—because in most human writing, that relationship is implicit. The rubric criterion defines a cognitive operation (articulating relevance) that requires the student to have actually performed that operation.\n\nThis approach draws on John Hattie and Helen Timperley's 2007 feedback model, which distinguishes feedback about the task, the process, and self-regulation. Criteria describing reasoning traces address the process level, where learning gains are largest.\n\n### Assess Transfer and Application\n\nTransfer criteria require students to apply a concept to a context not used in instruction. This is among the most robust measures of actual understanding versus surface memorization. Bransford, Brown, and Cocking's synthesis in *How People Learn* (1999, updated 2018) identified near and far transfer as reliable indicators of schema development.\n\nIn practice: replace \"accurately describes X concept\" with \"applies X concept to an unfamiliar case and identifies where the concept's predictions break down.\" An LLM can describe concepts accurately from training data. It cannot reliably know which case the instructor designated as \"unfamiliar\" or identify the specific failure mode the instructor expected students to find through their own reasoning.\n\n### Embed Metacognitive Dimensions\n\nAdd a rubric row that assesses the student's reflection on their own process: Where did their initial approach fail? What did they have to revise and why? What remains uncertain?\n\nResearch by Zimmerman and Moylan (2009) established that metacognitive monitoring—specifically, accurate recognition of one's own errors—is one of the strongest predictors of academic achievement across domains. A student who can identify where their argument is weak is demonstrating understanding. An LLM producing the same document has no genuine uncertainty to report.\n\nThis is not merely AI-resistant design. It is better assessment design that happens to be AI-resistant.\n\n## What does research say about co-creating rubrics?\n\nOne of the most consistently supported findings in rubric research is that student involvement in rubric creation improves learning outcomes. Andrade and Du (2005) found that students who participated in developing rubric criteria showed higher quality work and greater ownership of the assessment process than students who received instructor-created rubrics.\n\nThe mechanism appears to be the metacognitive activation that occurs when students must articulate what \"good\" looks like before they have produced anything. This forced articulation reveals gaps in their understanding of the task that they might otherwise discover only after submission.\n\nIn an AI-assisted classroom, co-creation takes on additional significance. An instructor can use an LLM to generate a draft rubric from a learning objective, then ask students to *critique and revise it*. What criteria are missing? What would a superficially good-looking but substantively hollow response look like for this criterion? Where does the rubric incentivize gaming?\n\nThis process positions students as rubric analysts—a metacognitive exercise in its own right—while also producing rubrics that are harder to game because students themselves have identified the failure modes.\n\n## What does research support in AI-assisted rubric generation?\n\nThe research on AI-generated rubric quality is nascent but directional. A 2024 study by Barrot found that LLM-generated rubrics for college writing tasks were rated comparable to expert-developed rubrics on clarity and coverage of relevant dimensions, but consistently weaker on *specificity*: the AI-generated rubrics tended to describe qualities at a level of abstraction that made reliable scoring difficult.\n\nThis finding maps onto a known problem in rubric design literature: criteria that are too abstract fail to anchor rater judgment, inflating inter-rater variability even when raters agree on the abstract dimension. Reddy and Andrade's 2010 systematic review identified criterion specificity as the most common failure mode in rubrics used in practice.\n\nThe practical workflow that the research supports is: use AI to generate coverage and structure, then apply human expertise to sharpen each criterion to the level of a concrete, observable behavior. The resulting rubric benefits from AI's broad awareness of what dimensions matter while retaining the specificity that only domain experts can provide for a particular task in a particular course context.\n\n## How should educators test rubric validity?\n\nRubric validity—whether a rubric actually measures what it claims to measure—has received sustained attention in the psychometric literature and is acutely relevant to the AI era.\n\nMoskal and Leydens (2000) described two core threats to rubric validity: **construct underrepresentation** (the rubric misses important dimensions of the target construct) and **construct-irrelevant variance** (the rubric rewards qualities that are unrelated to the learning objective, such as length or formatting).\n\nAI amplifies both threats. LLMs are specifically optimized to produce text that scores well on common rubric criteria, which means construct-irrelevant variance becomes a systematic bias rather than random noise. If a rubric rewards formal academic register, LLMs will produce formal academic register; if it rewards a minimum word count, LLMs will expand to fill it.\n\nValidity-aware rubric design in the AI era requires auditing every criterion with a single question: *Does this criterion measure the cognitive construct I care about, or does it measure a surface feature that correlates with it?* The second category should be eliminated or redesigned.\n\n## Why is a rubric a cognitive contract?\n\nThe best rubric research from the past two decades converges on a view of rubrics not as grading tools but as cognitive contracts: shared descriptions of what deep engagement with a task looks like, co-constructed between instructor and student, oriented toward process as much as product.\n\nThat view did not need AI to be true. But AI has made the alternative—rubrics as output checklists—untenable at scale. When the output can be generated without any of the cognition the rubric was designed to require, measuring the output is no longer measuring learning.\n\nRedesigning rubrics for the AI era does not require new theory. It requires applying the theory we already have, more rigorously, with the specific failure modes that AI introduces in view. The research is clear: criteria that describe cognitive operations, require transfer, embed metacognition, and are co-constructed with students produce better learning outcomes and are genuinely harder to satisfy without the thinking that produces quality work.\n\nThat is not a workaround. That is what good rubric design always looked like.\n\n---\n\n*Further reading: Andrade (2013) \"Reconsidering the Consequences of Using Assessment to Motivate\"; Jonsson & Svingby (2007) \"The Use of Scoring Rubrics: Reliability, Validity and Educational Consequences\"; Panadero & Jonsson (2013) \"The Use of Scoring Rubrics for Formative Assessment Purposes Revisited\"; Brookhart (2013) \"How to Create and Use Rubrics for Formative Assessment and Grading.\"*\n\n:::faq\n### What should an AI-era rubric measure?\n\nMeasure evidence tied to the learning goal: reasoning, source selection, decisions, revision, transfer, and reflection. Surface polish can remain a criterion when writing quality is the goal, but it should not stand in for understanding when a tool can produce it.\n\n### When should learners see the rubric?\n\nLearners should see and discuss the rubric before beginning assessed work. Early access makes criteria usable for planning and self-review. It also gives the educator time to clarify permitted AI support and the evidence each learner must provide independently.\n\n### Can AI draft a rubric?\n\nAI can propose language or examples, but the educator must verify alignment with the learning goal, remove ambiguous criteria, check accessibility, and test scoring consistency. The accountable human decides what counts as evidence and how performance affects a learner.\n:::\n\n[^1]: https://doi.org/10.1007/s10648-013-9241-y\n[^2]: https://tech.ed.gov/ai-future-of-teaching-and-learning/\n[^3]: https://udlguidelines.cast.org/\n[^4]: https://unesdoc.unesco.org/ark:/48223/pf0000386693\n[^5]: https://www.nist.gov/itl/ai-risk-management-framework\n[^6]: https://ies.ed.gov/ncee/wwc/PracticeGuides","author":"chase-willden","reviewer":null,"publishedAt":"2026-05-18","contentUpdatedAt":"2026-08-11","reviewedAt":null,"reviewDueOn":"2026-11-18","primaryQuestion":"How do you design a rubric that remains valid when students use AI?","cluster":"p2","pillar":"p2","briefRef":"2026-05-effective-rubrics-ai","verifiedAgainst":"","keywords":["rubric design","generative AI assessment","assessment validity"],"relatedTo":[],"roles":[],"segments":[],"citations":["https://doi.org/10.1007/s10648-013-9241-y","https://tech.ed.gov/ai-future-of-teaching-and-learning/","https://udlguidelines.cast.org/"],"extra":{"import":{"sourcePath":"www/src/blog/effective-rubrics-in-the-age-of-ai.md","gitSha":"079aacf8fef3b171a54b2063dce723471714b824","importedAt":"2026-08-12T00:00:00Z","lastmodSource":"frontmatter","sourceHash":"92b2668f90d3bad58ea547c390ac59b100388f112bf0e99e8660e8dea7ba3af0","importedRevision":1,"metadata":{"contentContract":"seo-6-v1"}},"seedMigration":"485"}},{"kind":"blog","slug":"rethinking-assessment-in-the-ai-era","category":null,"path":"/blog/rethinking-assessment-in-the-ai-era","title":"Beyond the Proctor: Rethinking Assessment in the Age of Generative AI","description":"Redesign assessment around process evidence, explanation, revision, and transfer instead of unreliable AI detection and surveillance.","bodyMd":":::key-takeaways\n- Assessment should collect evidence of learning instead of trying to prove that no tool was used.\n- Process checkpoints, explanation, and transfer make learner decisions visible.\n- AI can strengthen formative feedback when educators define its role and retain human judgment.\n:::\n\n:::answer\nAssessment should shift from policing finished products toward collecting valid evidence throughout the learning process. Ask learners to explain choices, apply ideas in unfamiliar contexts, revise from feedback, and disclose permitted AI use. Pair those tasks with clear criteria and accessible alternatives. Detection alone cannot establish what a learner understands.\n:::\n\nUse the [assessment guide](/resources/guides#p2), review [assessment tools](/platform/assessment), and compare the [rubric design approach](/blog/effective-rubrics-in-the-age-of-ai).\n\n## Why is AI detection a deadlock?\n\nSince the late 2022 explosion of Large Language Models (LLMs), educational institutions have been locked in a technological arms race. On one side are \"AI detectors\" that promise to identify synthetic text with high confidence. On the other side are increasingly sophisticated models—and clever prompting techniques—that render those detectors statistically unreliable.\n\nThe reality of 2026 is clear: **detection is a dead end.**\n\nRelying on proctoring software and AI detectors creates a hostile learning environment while failing to address the underlying pedagogical problem. If an assessment can be completed by an LLM in seconds without the student engaging in deep thought, then the assessment is no longer measuring what we think it is. We aren't facing a crisis of integrity; we are facing a crisis of assessment design.\n\n## How can assessment move from product to process?\n\nFor decades, assessment has focused on the *product*: the final essay, the completed lab report, the answered quiz. AI has commoditized the production of these artifacts. To maintain meaningful measurement, we must shift our focus to the *process*.\n\nIn a process-oriented assessment model, we don't just grade the final submission. We look at the trail of evidence that led there:\n- **Version History:** Assessing how an argument evolved over multiple drafts.\n- **Reflection Queries:** Asking students to explain *why* they made specific editorial choices.\n- **AI Collaboration Logs:** If AI was used, how was it prompted? How did the student verify its claims?\n\nBy assessing the journey, we make the \"product\" secondary. The learning happens in the synthesis, the critique, and the refinement—actions that require human agency even when assisted by digital tools.\n\n## How does formative assessment create a continuous signal?\n\nIn our previous post on [Adaptive AI](./adaptive-ai-and-education.md), we discussed how Item Response Theory (IRT) allows us to maintain a running estimate of a learner's ability. This technical foundation enables a shift from **summative** snapshots (the midterm) to **formative** continuous signals.\n\nWhen assessment is continuous and low-stakes, the incentive to cheat evaporates. If a student uses AI to \"fake\" their way through a daily calibration item, the system's estimate of their ability will temporarily spike, but the subsequent items will become increasingly difficult until the gap between their \"faked\" ability and their \"actual\" ability becomes insurmountable.\n\nContinuous assessment, powered by IRT, doesn't ask \"Did you pass the test?\" it asks \"What do you know right now, and how confident are we in that measurement?\"\n\n## What makes an assessment authentic in an AI era?\n\nAuthentic assessment involves tasks that mirror real-world applications of knowledge. While an LLM can write a generic essay on the causes of the French Revolution, it struggles with:\n- **Local Context:** Applying historical concepts to a specific, local community issue.\n- **Multi-Modal Synthesis:** Explaining a concept using a combination of text, hand-drawn diagrams, and oral defense.\n- **Personal Connection:** Linking abstract theories to the student's own lived experience or career goals.\n\nBy designing tasks that require situated knowledge and personal synthesis, we create assessments that are \"AI-resilient\" not through technical locks, but through pedagogical depth.\n\n## What role should AI have in feedback loops?\n\nThe most transformative use of AI in assessment isn't grading; it's feedback. Traditional grading is a \"post-mortem\"—it happens after the learning is over. AI-assisted feedback happens *during* the work.\n\nAn AI tutor can identify a misconception (using the detection logic we've integrated into Lextures) at the moment it appears. It can provide a scaffolding hint or a worked example that guides the student back to the correct path without giving away the answer. This turns every assessment into a learning opportunity, blurring the line between \"testing\" and \"teaching.\"\n\n## How can educators reclaim the assessment narrative?\n\nThe \"AI threat\" to academic integrity is only a threat to outdated modes of measurement. By embracing continuous, formative assessment and focusing on the human process of synthesis, we can move beyond the \"cat and mouse\" game of proctoring.\n\nAssessment shouldn't be a gate to be bypassed; it should be a mirror that shows the learner their own progress. In the age of AI, our job is to ensure that mirror remains clear, honest, and deeply integrated into the act of learning itself.\n\n:::faq\n### Why is AI detection insufficient for assessment?\n\nA detector cannot establish what a learner understands, and its output may be uncertain or wrong. Assessment needs affirmative evidence tied to the learning goal: explanations, checkpoints, decisions, revision, and transfer. Policy can govern disclosure without treating a detector score as proof.\n\n### What is process evidence?\n\nProcess evidence is material that makes learning decisions visible, such as notes, source choices, interim drafts, feedback responses, oral explanations, or a transfer task. Educators should collect only what they need and apply clear privacy and retention rules.\n\n### Does authentic assessment prohibit AI?\n\nNo. Authenticity comes from alignment with meaningful practice and valid evidence, not a blanket tool ban. Some tasks should permit AI because professionals use it; others should constrain assistance because independent performance is the learning goal.\n:::\n\n[^1]: https://www.nature.com/articles/s41562-023-01713-7\n[^2]: https://tech.ed.gov/ai-future-of-teaching-and-learning/\n[^3]: https://www.nist.gov/itl/ai-risk-management-framework","author":"chase-willden","reviewer":null,"publishedAt":"2026-05-15","contentUpdatedAt":"2026-08-11","reviewedAt":null,"reviewDueOn":"2026-11-15","primaryQuestion":"How should assessment change in the age of generative AI?","cluster":"p2","pillar":"p2","briefRef":"2026-05-rethinking-assessment-ai","verifiedAgainst":"","keywords":["AI assessment","authentic assessment","assessment validity"],"relatedTo":[],"roles":[],"segments":[],"citations":["https://www.nature.com/articles/s41562-023-01713-7","https://tech.ed.gov/ai-future-of-teaching-and-learning/","https://www.nist.gov/itl/ai-risk-management-framework"],"extra":{"import":{"sourcePath":"www/src/blog/rethinking-assessment-in-the-ai-era.md","gitSha":"079aacf8fef3b171a54b2063dce723471714b824","importedAt":"2026-08-12T00:00:00Z","lastmodSource":"frontmatter","sourceHash":"8017bd783f7911ed4337021f6f85412a31b81dc5966190318719f45193701eff","importedRevision":1,"metadata":{"contentContract":"seo-6-v1"}},"seedMigration":"485"}},{"kind":"blog","slug":"the-synthetic-renaissance","category":null,"path":"/blog/the-synthetic-renaissance","title":"The Synthetic Renaissance: How AI is Reshaping the Architecture of Learning","description":"Understand how accountable AI can support feedback and teaching while preserving educator judgment, learner agency, privacy, and access.","bodyMd":":::key-takeaways\n- AI can reduce repetitive production work but does not replace professional judgment or relationships.\n- Effective adoption redesigns feedback and teaching roles instead of adding an isolated tool.\n- Accessibility, privacy, evidence, and human oversight must be designed into the operating model.\n:::\n\n:::answer\nAI is changing teaching by moving some drafting, pattern detection, and feedback preparation into software, while making human judgment more important. A sound architecture connects those tools to explicit learning goals, accessible workflows, privacy controls, and educator review. The goal is better evidence and attention, not automated teaching.\n:::\n\nSee the [grading and integrity cluster](/resources/guides#p3), [accountable AI capabilities](/platform/ai), and [grading workflows](/platform/grading).\n\nThe global educational landscape is currently navigating a period of profound structural realignment. This evolution, often termed the **\"Synthetic Renaissance,\"** is not merely a technological upgrade but a fundamental re-engineering of how information is processed, retained, and applied by the human mind.\n\nAs of early 2026, evidence indicates that the integration of artificial intelligence (AI) has reached a critical inflection point. Market indicators suggest rapid expansion in the AI education sector. This growth is fueled by demand for personalized instruction and pressure created by the [global teacher shortage](https://www.unesco.org/en/articles/world-needs-44-million-teachers-reach-universal-primary-and-secondary-education-2030).\n\n## What is the cognitive performance paradox?\n\nThe central paradox of AI in education involves the disconnect between immediate performance gains and long-term learning durability. Causal research indicates that while students utilizing AI tools achieve significant improvements in task-related performance, these gains often dissipate or reverse when the technology is removed.\n\n### Cognitive Offloading and Human Memory\n\"Cognitive offloading\" describes the process where individuals externalize mental tasks to digital tools. While offloading lower-order tasks can free up resources for higher-order thinking, pervasive use of AI for content generation appears to be impacting the \"germane load\"—the mental effort required for knowledge schema construction.\n\nLongitudinal studies identify a significant negative correlation between frequent AI dependency and critical thinking skills. This is often mediated by a decline in active recall; when learners allow AI to process information, they bypass the **\"Generation Effect,\"** a cognitive principle where self-generated information is more likely to be retained than information that is simply consumed. A study involving high school mathematics students found that unguided usage improved practice performance but reduced independent exam performance.[^4]\n\n## How does AI change the teacher’s role?\n\nThe integration of AI is shifting the teaching profession from a focus on content delivery to a focus on facilitation and mentorship.\n\n### Efficiency and Administrative Mitigation\nBy early 2026, adoption rates among educators are soaring. The primary value proposition is the mitigation of administrative burdens. Special education teachers, for instance, have seen Individualized Education Program (IEP) preparation time drop from 3 hours to 10 minutes through automated platforms like Streamline.\n\nHowever, this gain is offset by \"invisible work\"—the time required to check, correct, and adapt AI-generated outputs for pedagogical accuracy.\n\n### The Source Attribution Effect\nOne of the more nuanced findings in 2025 research is the **\"source attribution effect.\"** Students' engagement with feedback is heavily influenced by who they believe provided it. In experiments where identical feedback was given, students who believed the feedback came from a human spent significantly more time on task. This underscores the importance of the [human element in motivation](https://www.oecd.org/education/2030-project/teaching-and-learning/learning/) and depth of processing.\n\n## How can AI support accessibility without widening divides?\n\nThe potential for AI to serve as a democratizing force is one of its most compelling attributes, offering solutions for neurodivergent learners and underserved regions.\n\n- **Maseno University (Kenya):** Researchers developed the [AI4KSL project](https://www.maseno.ac.ke/index.php/research/ai4ksl), which translates spoken English into Kenyan Sign Language using virtual avatars.\n- **RobotsMali (Mali):** Leveraging AI to produce over [180 children’s books in Bambara](https://www.robotsmali.org/), preserving local language and culture.\n- **India (NEP 2020):** AI is being used to [translate textbooks into 22 Indian languages](https://pib.gov.in/PressReleasePage.aspx?PRID=1943805), ensuring the benefits of digital transformation reach students in their mother tongues.\n\n## Which ethical safeguards should govern education AI?\n\nAs AI becomes infrastructural, governments are establishing regulatory frameworks to protect students' rights.\n\n- **EU AI Act:** Classifies AI used for admissions, grading, and behavior monitoring as [\"high-risk\"](https://www.europarl.europa.eu/news/en/headlines/society/20230601STO93804/eu-ai-act-first-regulation-on-artificial-intelligence). Notably, the Act prohibits emotion recognition in school environments.\n- **UK Safety Standards:** In 2026, the UK government established formal [safety standards](https://www.gov.uk/government/publications/generative-ai-in-education) for generative AI products in schools, mandating \"progressive disclosure\" to encourage critical thinking.\n- **UNESCO Guidance:** The [UNESCO Global Guidance](https://www.unesco.org/en/articles/unesco-releases-first-global-guidance-generative-ai-education-and-research) advocates for a human-centered approach and recommends age limits for AI tool usage.\n\n## What might education AI look like by 2030?\n\nBy 2030, the classroom will move beyond physical boundaries, influenced by immersive VR/AR and the reorganization of learning. We are seeing a shift away from traditional, monolithic degrees toward **\"skill wallets\"**—verified portfolios of micro-credentials authenticated by AI.\n\n### Conclusion: The Human Foundation\nDespite the expansion of digital tools, the relational foundation of the classroom remains indispensable. The impact of AI on learning will ultimately depend on whether it is governed as a partner that enhances teacher agency or as an automated replacement that leads to cognitive atrophy.\n\nAI has the power to transform the classroom into a highly personalized and efficient space, but only if its deployment is guided by a commitment to preserving human agency and critical scrutiny.\n\n:::faq\n### Will AI replace teachers?\n\nAI can assist with repetitive production, pattern detection, and feedback preparation, but teaching also requires accountable judgment, relationships, context, and care. Institutions should evaluate which work a tool supports and keep educators responsible for decisions that affect learners.\n\n### What should schools govern before adopting education AI?\n\nSchools should define purpose, allowed data, retention, human review, accessibility, vendor accountability, incident response, and a way to challenge outcomes. They should also identify the evidence that would justify continuing, changing, or stopping the use.\n\n### How can AI support accessible learning?\n\nAI may help transform formats or draft alternatives, but generated material still needs accessibility and accuracy review. Learners need equivalent paths, clear controls, and a human contact when automation fails. Accessibility should be tested with users rather than inferred from a feature list.\n:::\n\n[^1]: https://unesdoc.unesco.org/ark:/48223/pf0000386693\n[^2]: https://tech.ed.gov/ai-future-of-teaching-and-learning/\n[^3]: https://www.nist.gov/itl/ai-risk-management-framework\n[^4]: https://www.nature.com/articles/s41598-024-52321-x","author":"chase-willden","reviewer":null,"publishedAt":"2026-05-06","contentUpdatedAt":"2026-08-11","reviewedAt":null,"reviewDueOn":"2026-11-06","primaryQuestion":"How is AI changing the architecture of teaching and feedback?","cluster":"p3","pillar":"p3","briefRef":"2026-05-synthetic-renaissance","verifiedAgainst":"","keywords":["AI in education","teaching with AI","AI feedback"],"relatedTo":[],"roles":[],"segments":[],"citations":["https://unesdoc.unesco.org/ark:/48223/pf0000386693","https://tech.ed.gov/ai-future-of-teaching-and-learning/","https://www.nist.gov/itl/ai-risk-management-framework"],"extra":{"import":{"sourcePath":"www/src/blog/the-synthetic-renaissance.md","gitSha":"079aacf8fef3b171a54b2063dce723471714b824","importedAt":"2026-08-12T00:00:00Z","lastmodSource":"frontmatter","sourceHash":"56e7493222415b9eb83112ec5cc41c0e1211e5044ffffa2b03506379fa175c86","importedRevision":1,"metadata":{"contentContract":"seo-6-v1"}},"seedMigration":"485"}},{"kind":"doc","slug":"accessible-content-authoring","category":"accessibility","path":"/docs/accessibility/accessible-content-authoring","title":"Authoring accessible course content","description":"Use headings, link text, alternatives, captions, tables, and checks that help learners navigate course material. Learn the key checks and safe next steps..","bodyMd":"::: key-takeaways\n- Use headings, link text, alternatives, captions, tables, and checks that help learners navigate course material.\n- Confirm the available controls in your own organization because permissions and enabled features determine what appears.\n- Use a test record or limited pilot first, then review the resulting learner and administrator experience.\n:::\n\n::: answer\nUse headings, link text, alternatives, captions, tables, and checks that help learners navigate course material. Open the relevant settings, confirm your role permits the change, test with limited scope, and review the result from the affected user's view. Keep organization policy and learner privacy in the approval path.\n:::\n\n## Who can use this feature?\n\nThis guide applies to **instructor** roles in K–12, higher education, and homeschool settings. The exact control is shown only when the signed-in person has the required permission and the capability is enabled for the organization. Global access does not replace course or organization policy. If the named page or action is absent, ask an administrator to confirm permissions before changing configuration.\n\n## How do you complete the task?\n\n::: steps\n1. Open the course, account, or organization area named by the feature and confirm that you are working in the intended scope.\n2. Review the current value and any dependent settings before editing it. Record the starting state when a rollback may be needed.\n3. Make the smallest required change, using synthetic or limited test data when the workflow affects people, grades, identity, or integrations.\n4. Save the change and verify it from the affected role's view. Check both the expected result and access that should remain unavailable.\n5. Communicate the change when it alters learner access, deadlines, grading, sign-in, data handling, or a connected system.\n:::\n\nLextures exposes only controls supported by the deployed version. Self-hosted operators should compare their release and configuration with the current project source.[^1] Screens and labels can change between releases, so the verification step is part of the procedure rather than an optional cleanup task.\n\n## What should you check afterward?\n\nConfirm that the expected person can see or perform the intended action and that unrelated users cannot. Review any audit, delivery, synchronization, or status information the feature provides. For a workflow that exchanges data, compare a small sample at both ends instead of assuming that a successful request means every record was applied.\n\nKeep a support-safe note of the scope, time, and outcome. Do not copy passwords, tokens, accommodation details, or unnecessary learner records into that note. For broader context, visit the [help center](/docs), the [accessibility help category](/docs/accessibility), and [Lextures platform overview](/platform). See also [How accommodations are applied automatically](/docs/accessibility/automatic-accommodations), [Which WCAG 2.2 AA features Lextures supports](/docs/accessibility/wcag-22-aa-features), and [Setting learner accommodations](/docs/accessibility/setting-learner-accommodations).\n\nThe public platform overview provides the product context used by this help article.[^2]\n\n::: faq\n### Why can I not see this setting?\nYour role, organization policy, course state, or deployed version may not expose it. Confirm that you are in the correct organization or course, then ask an administrator to review the relevant permission and feature configuration. Avoid working around a missing control with shared credentials.\n\n### Should I test the change first?\nYes. Use the smallest realistic scope and synthetic data where possible. For identity, roster, grading, accommodation, payment, or integration changes, verify both the intended path and a user who should remain unaffected before expanding the configuration.\n\n### What information should I send to support?\nSend the page name, approximate time, your role, the affected scope, and a description of expected and observed behavior. Remove learner records and secrets. Include a screenshot only when it contains synthetic data or has been reviewed and redacted.\n:::\n\n[^1]: https://github.com/lextures/lextures\n[^2]: https://lextures.com/platform","author":"chase-willden","reviewer":null,"publishedAt":"2026-08-11","contentUpdatedAt":"2026-08-11","reviewedAt":null,"reviewDueOn":"2027-02-11","primaryQuestion":"How do I use authoring accessible course content in Lextures?","cluster":"help-accessibility","pillar":"","briefRef":"","verifiedAgainst":"2026-08-11 source","keywords":["Lextures","accessibility","help"],"relatedTo":["/docs/accessibility/automatic-accommodations","/docs/accessibility/wcag-22-aa-features","/docs/accessibility/setting-learner-accommodations"],"roles":["instructor"],"segments":["k12","higher-ed","homeschool"],"citations":[],"extra":{"import":{"sourcePath":"www/src/docs/accessibility/accessible-content-authoring.md","gitSha":"079aacf8fef3b171a54b2063dce723471714b824","importedAt":"2026-08-12T00:00:00Z","lastmodSource":"frontmatter","sourceHash":"c57e2cf3bf86030c6a86b47b0461e245a646040e792615166a3957a829425d86","importedRevision":1,"metadata":{"contentContract":"answer-first-v1","supportTicketThemes":["accessibility-accessible-content-authoring"]}},"seedMigration":"485"}},{"kind":"doc","slug":"automatic-accommodations","category":"accessibility","path":"/docs/accessibility/automatic-accommodations","title":"How accommodations are applied automatically","description":"Understand how authorized learner accommodations affect supported activities while preserving the underlying course requirements. Learn the key checks and saf.","bodyMd":"::: key-takeaways\n- Understand how authorized learner accommodations affect supported activities while preserving the underlying course requirements.\n- Confirm the available controls in your own organization because permissions and enabled features determine what appears.\n- Use a test record or limited pilot first, then review the resulting learner and administrator experience.\n:::\n\n::: answer\nUnderstand how authorized learner accommodations affect supported activities while preserving the underlying course requirements. Open the relevant settings, confirm your role permits the change, test with limited scope, and review the result from the affected user's view. Keep organization policy and learner privacy in the approval path.\n:::\n\n## Who can use this feature?\n\nThis guide applies to **instructor, admin** roles in K–12, higher education, and homeschool settings. The exact control is shown only when the signed-in person has the required permission and the capability is enabled for the organization. Global access does not replace course or organization policy. If the named page or action is absent, ask an administrator to confirm permissions before changing configuration.\n\n## How do you complete the task?\n\n::: steps\n1. Open the course, account, or organization area named by the feature and confirm that you are working in the intended scope.\n2. Review the current value and any dependent settings before editing it. Record the starting state when a rollback may be needed.\n3. Make the smallest required change, using synthetic or limited test data when the workflow affects people, grades, identity, or integrations.\n4. Save the change and verify it from the affected role's view. Check both the expected result and access that should remain unavailable.\n5. Communicate the change when it alters learner access, deadlines, grading, sign-in, data handling, or a connected system.\n:::\n\nLextures exposes only controls supported by the deployed version. Self-hosted operators should compare their release and configuration with the current project source.[^1] Screens and labels can change between releases, so the verification step is part of the procedure rather than an optional cleanup task.\n\n## What should you check afterward?\n\nConfirm that the expected person can see or perform the intended action and that unrelated users cannot. Review any audit, delivery, synchronization, or status information the feature provides. For a workflow that exchanges data, compare a small sample at both ends instead of assuming that a successful request means every record was applied.\n\nKeep a support-safe note of the scope, time, and outcome. Do not copy passwords, tokens, accommodation details, or unnecessary learner records into that note. For broader context, visit the [help center](/docs), the [accessibility help category](/docs/accessibility), and [Lextures platform overview](/platform). See also [Which WCAG 2.2 AA features Lextures supports](/docs/accessibility/wcag-22-aa-features), [Setting learner accommodations](/docs/accessibility/setting-learner-accommodations), and [Authoring accessible course content](/docs/accessibility/accessible-content-authoring).\n\nThe public platform overview provides the product context used by this help article.[^2]\n\n::: faq\n### Why can I not see this setting?\nYour role, organization policy, course state, or deployed version may not expose it. Confirm that you are in the correct organization or course, then ask an administrator to review the relevant permission and feature configuration. Avoid working around a missing control with shared credentials.\n\n### Should I test the change first?\nYes. Use the smallest realistic scope and synthetic data where possible. For identity, roster, grading, accommodation, payment, or integration changes, verify both the intended path and a user who should remain unaffected before expanding the configuration.\n\n### What information should I send to support?\nSend the page name, approximate time, your role, the affected scope, and a description of expected and observed behavior. Remove learner records and secrets. Include a screenshot only when it contains synthetic data or has been reviewed and redacted.\n:::\n\n[^1]: https://github.com/lextures/lextures\n[^2]: https://lextures.com/platform","author":"chase-willden","reviewer":null,"publishedAt":"2026-08-11","contentUpdatedAt":"2026-08-11","reviewedAt":null,"reviewDueOn":"2027-02-11","primaryQuestion":"How do I use how accommodations are applied automatically in Lextures?","cluster":"help-accessibility","pillar":"","briefRef":"","verifiedAgainst":"2026-08-11 source","keywords":["Lextures","accessibility","help"],"relatedTo":["/docs/accessibility/wcag-22-aa-features","/docs/accessibility/setting-learner-accommodations","/docs/accessibility/accessible-content-authoring"],"roles":["instructor","admin"],"segments":["k12","higher-ed","homeschool"],"citations":[],"extra":{"import":{"sourcePath":"www/src/docs/accessibility/automatic-accommodations.md","gitSha":"079aacf8fef3b171a54b2063dce723471714b824","importedAt":"2026-08-12T00:00:00Z","lastmodSource":"frontmatter","sourceHash":"70d0f7d859c9169cb3d33538af39a552168c8591ff55f587da03a8f9733c5886","importedRevision":1,"metadata":{"contentContract":"answer-first-v1","supportTicketThemes":["accessibility-automatic-accommodations"]}},"seedMigration":"485"}},{"kind":"doc","slug":"setting-learner-accommodations","category":"accessibility","path":"/docs/accessibility/setting-learner-accommodations","title":"Setting learner accommodations","description":"Record an approved accommodation, limit its scope, verify the learner experience, and keep sensitive details out of notes. Learn the key checks and safe next.","bodyMd":"::: key-takeaways\n- Record an approved accommodation, limit its scope, verify the learner experience, and keep sensitive details out of notes.\n- Confirm the available controls in your own organization because permissions and enabled features determine what appears.\n- Use a test record or limited pilot first, then review the resulting learner and administrator experience.\n:::\n\n::: answer\nRecord an approved accommodation, limit its scope, verify the learner experience, and keep sensitive details out of notes. Open the relevant settings, confirm your role permits the change, test with limited scope, and review the result from the affected user's view. Keep organization policy and learner privacy in the approval path.\n:::\n\n## Who can use this feature?\n\nThis guide applies to **instructor, admin** roles in K–12, higher education, and homeschool settings. The exact control is shown only when the signed-in person has the required permission and the capability is enabled for the organization. Global access does not replace course or organization policy. If the named page or action is absent, ask an administrator to confirm permissions before changing configuration.\n\n## How do you complete the task?\n\n::: steps\n1. Open the course, account, or organization area named by the feature and confirm that you are working in the intended scope.\n2. Review the current value and any dependent settings before editing it. Record the starting state when a rollback may be needed.\n3. Make the smallest required change, using synthetic or limited test data when the workflow affects people, grades, identity, or integrations.\n4. Save the change and verify it from the affected role's view. Check both the expected result and access that should remain unavailable.\n5. Communicate the change when it alters learner access, deadlines, grading, sign-in, data handling, or a connected system.\n:::\n\nLextures exposes only controls supported by the deployed version. Self-hosted operators should compare their release and configuration with the current project source.[^1] Screens and labels can change between releases, so the verification step is part of the procedure rather than an optional cleanup task.\n\n## What should you check afterward?\n\nConfirm that the expected person can see or perform the intended action and that unrelated users cannot. Review any audit, delivery, synchronization, or status information the feature provides. For a workflow that exchanges data, compare a small sample at both ends instead of assuming that a successful request means every record was applied.\n\nKeep a support-safe note of the scope, time, and outcome. Do not copy passwords, tokens, accommodation details, or unnecessary learner records into that note. For broader context, visit the [help center](/docs), the [accessibility help category](/docs/accessibility), and [Lextures platform overview](/platform). See also [How accommodations are applied automatically](/docs/accessibility/automatic-accommodations), [Which WCAG 2.2 AA features Lextures supports](/docs/accessibility/wcag-22-aa-features), and [Authoring accessible course content](/docs/accessibility/accessible-content-authoring).\n\nThe public platform overview provides the product context used by this help article.[^2]\n\n::: faq\n### Why can I not see this setting?\nYour role, organization policy, course state, or deployed version may not expose it. Confirm that you are in the correct organization or course, then ask an administrator to review the relevant permission and feature configuration. Avoid working around a missing control with shared credentials.\n\n### Should I test the change first?\nYes. Use the smallest realistic scope and synthetic data where possible. For identity, roster, grading, accommodation, payment, or integration changes, verify both the intended path and a user who should remain unaffected before expanding the configuration.\n\n### What information should I send to support?\nSend the page name, approximate time, your role, the affected scope, and a description of expected and observed behavior. Remove learner records and secrets. Include a screenshot only when it contains synthetic data or has been reviewed and redacted.\n:::\n\n[^1]: https://github.com/lextures/lextures\n[^2]: https://lextures.com/platform","author":"chase-willden","reviewer":null,"publishedAt":"2026-08-11","contentUpdatedAt":"2026-08-11","reviewedAt":null,"reviewDueOn":"2027-02-11","primaryQuestion":"How do I use setting learner accommodations in Lextures?","cluster":"help-accessibility","pillar":"","briefRef":"","verifiedAgainst":"2026-08-11 source","keywords":["Lextures","accessibility","help"],"relatedTo":["/docs/accessibility/automatic-accommodations","/docs/accessibility/wcag-22-aa-features","/docs/accessibility/accessible-content-authoring"],"roles":["instructor","admin"],"segments":["k12","higher-ed","homeschool"],"citations":[],"extra":{"import":{"sourcePath":"www/src/docs/accessibility/setting-learner-accommodations.md","gitSha":"079aacf8fef3b171a54b2063dce723471714b824","importedAt":"2026-08-12T00:00:00Z","lastmodSource":"frontmatter","sourceHash":"abe971abe54a8d8038aad12632e3f9d83ee428761000a91606e8b2290a2abba5","importedRevision":1,"metadata":{"contentContract":"answer-first-v1","supportTicketThemes":["accessibility-setting-learner-accommodations"]}},"seedMigration":"485"}},{"kind":"doc","slug":"wcag-22-aa-features","category":"accessibility","path":"/docs/accessibility/wcag-22-aa-features","title":"Which WCAG 2.2 AA features Lextures supports","description":"Review keyboard, focus, semantics, contrast, zoom, and assistive-technology support alongside the current conformance report. Learn the key checks and safe ne.","bodyMd":"::: key-takeaways\n- Review keyboard, focus, semantics, contrast, zoom, and assistive-technology support alongside the current conformance report.\n- Confirm the available controls in your own organization because permissions and enabled features determine what appears.\n- Use a test record or limited pilot first, then review the resulting learner and administrator experience.\n:::\n\n::: answer\nReview keyboard, focus, semantics, contrast, zoom, and assistive-technology support alongside the current conformance report. Open the relevant settings, confirm your role permits the change, test with limited scope, and review the result from the affected user's view. Keep organization policy and learner privacy in the approval path.\n:::\n\n## Who can use this feature?\n\nThis guide applies to **instructor, admin** roles in K–12, higher education, and homeschool settings. The exact control is shown only when the signed-in person has the required permission and the capability is enabled for the organization. Global access does not replace course or organization policy. If the named page or action is absent, ask an administrator to confirm permissions before changing configuration.\n\n## How do you complete the task?\n\n::: steps\n1. Open the course, account, or organization area named by the feature and confirm that you are working in the intended scope.\n2. Review the current value and any dependent settings before editing it. Record the starting state when a rollback may be needed.\n3. Make the smallest required change, using synthetic or limited test data when the workflow affects people, grades, identity, or integrations.\n4. Save the change and verify it from the affected role's view. Check both the expected result and access that should remain unavailable.\n5. Communicate the change when it alters learner access, deadlines, grading, sign-in, data handling, or a connected system.\n:::\n\nLextures exposes only controls supported by the deployed version. Self-hosted operators should compare their release and configuration with the current project source.[^1] Screens and labels can change between releases, so the verification step is part of the procedure rather than an optional cleanup task.\n\n## What should you check afterward?\n\nConfirm that the expected person can see or perform the intended action and that unrelated users cannot. Review any audit, delivery, synchronization, or status information the feature provides. For a workflow that exchanges data, compare a small sample at both ends instead of assuming that a successful request means every record was applied.\n\nKeep a support-safe note of the scope, time, and outcome. Do not copy passwords, tokens, accommodation details, or unnecessary learner records into that note. For broader context, visit the [help center](/docs), the [accessibility help category](/docs/accessibility), and [Lextures platform overview](/platform). See also [How accommodations are applied automatically](/docs/accessibility/automatic-accommodations), [Setting learner accommodations](/docs/accessibility/setting-learner-accommodations), and [Authoring accessible course content](/docs/accessibility/accessible-content-authoring).\n\nThe public platform overview provides the product context used by this help article.[^2]\n\n::: faq\n### Why can I not see this setting?\nYour role, organization policy, course state, or deployed version may not expose it. Confirm that you are in the correct organization or course, then ask an administrator to review the relevant permission and feature configuration. Avoid working around a missing control with shared credentials.\n\n### Should I test the change first?\nYes. Use the smallest realistic scope and synthetic data where possible. For identity, roster, grading, accommodation, payment, or integration changes, verify both the intended path and a user who should remain unaffected before expanding the configuration.\n\n### What information should I send to support?\nSend the page name, approximate time, your role, the affected scope, and a description of expected and observed behavior. Remove learner records and secrets. Include a screenshot only when it contains synthetic data or has been reviewed and redacted.\n:::\n\n[^1]: https://github.com/lextures/lextures\n[^2]: https://lextures.com/platform","author":"chase-willden","reviewer":null,"publishedAt":"2026-08-11","contentUpdatedAt":"2026-08-11","reviewedAt":null,"reviewDueOn":"2027-02-11","primaryQuestion":"How do I use which wcag 2.2 aa features lextures supports in Lextures?","cluster":"help-accessibility","pillar":"","briefRef":"","verifiedAgainst":"2026-08-11 source","keywords":["Lextures","accessibility","help"],"relatedTo":["/docs/accessibility/automatic-accommodations","/docs/accessibility/setting-learner-accommodations","/docs/accessibility/accessible-content-authoring"],"roles":["instructor","admin"],"segments":["k12","higher-ed","homeschool"],"citations":[],"extra":{"import":{"sourcePath":"www/src/docs/accessibility/wcag-22-aa-features.md","gitSha":"079aacf8fef3b171a54b2063dce723471714b824","importedAt":"2026-08-12T00:00:00Z","lastmodSource":"frontmatter","sourceHash":"e885b9a4b6e97457cd47e3b989e719d8fbc3d57ac8d6fcbc823578e8654b63e0","importedRevision":1,"metadata":{"contentContract":"answer-first-v1","supportTicketThemes":["accessibility-wcag-22-aa-features"]}},"seedMigration":"485"}},{"kind":"doc","slug":"managing-active-sessions","category":"accounts","path":"/docs/accounts/managing-active-sessions","title":"Reviewing and ending active sessions","description":"Inspect account sessions, end ones you do not recognize, and follow the security response path when access looks suspicious. Learn the key checks and safe nex.","bodyMd":"::: key-takeaways\n- Inspect account sessions, end ones you do not recognize, and follow the security response path when access looks suspicious.\n- Confirm the available controls in your own organization because permissions and enabled features determine what appears.\n- Use a test record or limited pilot first, then review the resulting learner and administrator experience.\n:::\n\n::: answer\nInspect account sessions, end ones you do not recognize, and follow the security response path when access looks suspicious. Open the relevant settings, confirm your role permits the change, test with limited scope, and review the result from the affected user's view. Keep organization policy and learner privacy in the approval path.\n:::\n\n## Who can use this feature?\n\nThis guide applies to **admin, instructor, learner** roles in K–12, higher education, and homeschool settings. The exact control is shown only when the signed-in person has the required permission and the capability is enabled for the organization. Global access does not replace course or organization policy. If the named page or action is absent, ask an administrator to confirm permissions before changing configuration.\n\n## How do you complete the task?\n\n::: steps\n1. Open the course, account, or organization area named by the feature and confirm that you are working in the intended scope.\n2. Review the current value and any dependent settings before editing it. Record the starting state when a rollback may be needed.\n3. Make the smallest required change, using synthetic or limited test data when the workflow affects people, grades, identity, or integrations.\n4. Save the change and verify it from the affected role's view. Check both the expected result and access that should remain unavailable.\n5. Communicate the change when it alters learner access, deadlines, grading, sign-in, data handling, or a connected system.\n:::\n\nLextures exposes only controls supported by the deployed version. Self-hosted operators should compare their release and configuration with the current project source.[^1] Screens and labels can change between releases, so the verification step is part of the procedure rather than an optional cleanup task.\n\n## What should you check afterward?\n\nConfirm that the expected person can see or perform the intended action and that unrelated users cannot. Review any audit, delivery, synchronization, or status information the feature provides. For a workflow that exchanges data, compare a small sample at both ends instead of assuming that a successful request means every record was applied.\n\nKeep a support-safe note of the scope, time, and outcome. Do not copy passwords, tokens, accommodation details, or unnecessary learner records into that note. For broader context, visit the [help center](/docs), the [accounts help category](/docs/accounts), and [Lextures platform overview](/platform). See also [Setting up SAML/OIDC single sign-on](/docs/accounts/setting-up-saml-oidc-sso), [Setting up multifactor authentication](/docs/accounts/setting-up-mfa), and [Resetting your password](/docs/accounts/resetting-your-password).\n\nThe public platform overview provides the product context used by this help article.[^2]\n\n::: faq\n### Why can I not see this setting?\nYour role, organization policy, course state, or deployed version may not expose it. Confirm that you are in the correct organization or course, then ask an administrator to review the relevant permission and feature configuration. Avoid working around a missing control with shared credentials.\n\n### Should I test the change first?\nYes. Use the smallest realistic scope and synthetic data where possible. For identity, roster, grading, accommodation, payment, or integration changes, verify both the intended path and a user who should remain unaffected before expanding the configuration.\n\n### What information should I send to support?\nSend the page name, approximate time, your role, the affected scope, and a description of expected and observed behavior. Remove learner records and secrets. Include a screenshot only when it contains synthetic data or has been reviewed and redacted.\n:::\n\n[^1]: https://github.com/lextures/lextures\n[^2]: htt